import json
import itertools

def solve_puzzle():
    # Input variables
    houses = [1, 2, 3]  # Left (1) to right (3)
    names = ["Eric", "Arnold", "Peter"]
    heights = ["short", "very short", "average"]

    solutions = []

    for name_perm in itertools.permutations(names):
        # Constraints: Eric not in house 1, Arnold not in house 1
        if name_perm[0] == "Eric" or name_perm[0] == "Arnold":
            continue

        for height_perm in itertools.permutations(heights):
            # Find positions
            pos = { "Eric": name_perm.index("Eric"),
                    "Arnold": name_perm.index("Arnold"),
                    "Peter": name_perm.index("Peter") }

            hpos = { "short": height_perm.index("short"),
                     "very short": height_perm.index("very short"),
                     "average": height_perm.index("average") }

            # Constraint 3: Eric is the very short person
            if pos["Eric"] != hpos["very short"]:
                continue

            # Constraint 2: very short is left of short
            if not (hpos["very short"] < hpos["short"]):
                continue

            # All constraints satisfied
            solutions.append((name_perm, height_perm))

    # Assuming a unique solution
    if not solutions:
        raise ValueError("No solution found.")
    # If multiple, select the first for output (puzzle intended to be unique)
    name_solution, height_solution = solutions[0]

    output = {
        "solution": {
            "header": ["House", "Name", "Height"],
            "rows": [
                [str(houses[i]), name_solution[i], height_solution[i]] for i in range(len(houses))
            ]
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
